CREATE TABLE `core_contacts` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NULL, `email` VARCHAR(191) NULL, `notes` TEXT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `core_contacts_phone_idx` (`phone`), INDEX `core_contacts_email_idx` (`email`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `core_contact_sources` (`id` VARCHAR(191) NOT NULL, `contact_id` VARCHAR(191) NOT NULL, `source` VARCHAR(191) NOT NULL, `source_id` VARCHAR(191) NOT NULL, `role` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `phone` VARCHAR(191) NULL, `email` VARCHAR(191) NULL, `synced_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `core_contact_sources_source_source_id_key` (`source`,`source_id`), CONSTRAINT `core_contact_sources_contact_id_fkey` FOREIGN KEY (`contact_id`) REFERENCES `core_contacts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `core_expenses` (`id` VARCHAR(191) NOT NULL, `account_id` VARCHAR(191) NOT NULL, `module_source` VARCHAR(191) NOT NULL, `fund_type` VARCHAR(191) NOT NULL, `amount` INTEGER NOT NULL, `description` TEXT NOT NULL, `reference` VARCHAR(191) NOT NULL, `spent_at` DATETIME(3) NOT NULL, `created_by` VARCHAR(191) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `core_expenses_reference_key` (`reference`), INDEX `core_expenses_account_id_spent_at_idx` (`account_id`,`spent_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `core_bank_lines` (`id` VARCHAR(191) NOT NULL, `account_id` VARCHAR(191) NOT NULL, `booked_at` DATETIME(3) NOT NULL, `reference` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `direction` VARCHAR(191) NOT NULL, `amount` INTEGER NOT NULL, `fingerprint` VARCHAR(191) NOT NULL, `payment_id` VARCHAR(191) NULL, `expense_id` VARCHAR(191) NULL, `match_note` TEXT NULL, `matched_by` VARCHAR(191) NULL, `matched_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `core_bank_lines_fingerprint_key` (`fingerprint`), UNIQUE INDEX `core_bank_lines_payment_id_key` (`payment_id`), UNIQUE INDEX `core_bank_lines_expense_id_key` (`expense_id`), INDEX `core_bank_lines_account_id_booked_at_idx` (`account_id`,`booked_at`), CONSTRAINT `core_bank_lines_expense_id_fkey` FOREIGN KEY (`expense_id`) REFERENCES `core_expenses` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
